//! `wasm-bindgen` bindings for [`finance_tools`].
//!
//! This crate is a build input of the `finance-tools` npm package
//! (`packages/finance-tools`), which wraps the generated glue in its own
//! TypeScript API. It is not published to crates.io.
//!
//! Dates cross the boundary as ISO 8601 calendar date strings (`YYYY-MM-DD`).
//! JavaScript `Date` objects are deliberately not accepted: they are instants,
//! and converting them to a civil date depends on a time zone.

// The code generated by `#[wasm_bindgen]` for C-style enums compares the
// incoming ABI value as `f64`.
#![allow(
    clippy::float_cmp,
    reason = "triggered by #[wasm_bindgen] enum expansion"
)]

use jiff::civil::Date;
use wasm_bindgen::prelude::{JsError, wasm_bindgen};

use finance_tools::DayCountConvention;

// Mirrors `DayCountConvention`; the exhaustive conversions below make any
// drift between the two a compile error.
/// A day count convention. See the Rust crate documentation of
/// `finance_tools::DayCountConvention` for the exact semantics of each.
#[wasm_bindgen(js_name = DayCountConvention)]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum JsDayCountConvention {
    /// `1/1`
    OneOne,
    /// `Act/360`
    Actual360,
    /// `Act/364`
    Actual364,
    /// `Act/366`
    Actual366,
    /// `Act/365.25`
    Actual365_25,
    /// `Act/365 Actual`
    Actual365Actual,
    /// `Act/365F`
    Actual365Fixed,
    /// `Act/365L`
    Actual365Leap,
    /// `Act/Act AFB`
    ActualActualAfb,
    /// `Act/Act ISDA`
    ActualActualIsda,
    /// `NL/360`
    NoLeap360,
    /// `NL/365`
    NoLeap365,
    /// `30/360 ISDA`
    Thirty360Isda,
    /// `30E/360`
    ThirtyE360,
    /// `30E/360 ISDA`
    ThirtyE360Isda,
    /// `30E/365`
    ThirtyE365,
    /// `30E+/360`
    ThirtyEPlus360,
    /// `30U/360`
    ThirtyU360,
}

impl From<JsDayCountConvention> for DayCountConvention {
    fn from(convention: JsDayCountConvention) -> Self {
        use JsDayCountConvention as Js;
        match convention {
            Js::OneOne => Self::OneOne,
            Js::Actual360 => Self::Actual360,
            Js::Actual364 => Self::Actual364,
            Js::Actual366 => Self::Actual366,
            Js::Actual365_25 => Self::Actual365_25,
            Js::Actual365Actual => Self::Actual365Actual,
            Js::Actual365Fixed => Self::Actual365Fixed,
            Js::Actual365Leap => Self::Actual365Leap,
            Js::ActualActualAfb => Self::ActualActualAfb,
            Js::ActualActualIsda => Self::ActualActualIsda,
            Js::NoLeap360 => Self::NoLeap360,
            Js::NoLeap365 => Self::NoLeap365,
            Js::Thirty360Isda => Self::Thirty360Isda,
            Js::ThirtyE360 => Self::ThirtyE360,
            Js::ThirtyE360Isda => Self::ThirtyE360Isda,
            Js::ThirtyE365 => Self::ThirtyE365,
            Js::ThirtyEPlus360 => Self::ThirtyEPlus360,
            Js::ThirtyU360 => Self::ThirtyU360,
        }
    }
}

impl From<DayCountConvention> for JsDayCountConvention {
    fn from(convention: DayCountConvention) -> Self {
        use DayCountConvention as Rs;
        match convention {
            Rs::OneOne => Self::OneOne,
            Rs::Actual360 => Self::Actual360,
            Rs::Actual364 => Self::Actual364,
            Rs::Actual366 => Self::Actual366,
            Rs::Actual365_25 => Self::Actual365_25,
            Rs::Actual365Actual => Self::Actual365Actual,
            Rs::Actual365Fixed => Self::Actual365Fixed,
            Rs::Actual365Leap => Self::Actual365Leap,
            Rs::ActualActualAfb => Self::ActualActualAfb,
            Rs::ActualActualIsda => Self::ActualActualIsda,
            Rs::NoLeap360 => Self::NoLeap360,
            Rs::NoLeap365 => Self::NoLeap365,
            Rs::Thirty360Isda => Self::Thirty360Isda,
            Rs::ThirtyE360 => Self::ThirtyE360,
            Rs::ThirtyE360Isda => Self::ThirtyE360Isda,
            Rs::ThirtyE365 => Self::ThirtyE365,
            Rs::ThirtyEPlus360 => Self::ThirtyEPlus360,
            Rs::ThirtyU360 => Self::ThirtyU360,
        }
    }
}

fn parse_date(field: &str, value: &str) -> Result<Date, JsError> {
    value
        .parse()
        .map_err(|err| JsError::new(&format!("invalid {field} date {value:?}: {err}")))
}

/// Computes the year fraction between two ISO 8601 dates (`YYYY-MM-DD`).
///
/// # Errors
///
/// Throws if either date is not a valid ISO 8601 calendar date.
#[wasm_bindgen(js_name = yearFraction)]
pub fn year_fraction(
    convention: JsDayCountConvention,
    start: &str,
    end: &str,
) -> Result<f64, JsError> {
    let convention = DayCountConvention::from(convention);
    Ok(convention.year_fraction(parse_date("start", start)?, parse_date("end", end)?))
}

/// Returns the conventional market name of a day count convention, e.g.
/// `"Act/365F"`.
#[wasm_bindgen(js_name = conventionName)]
#[must_use]
pub fn convention_name(convention: JsDayCountConvention) -> String {
    DayCountConvention::from(convention).name().to_owned()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn conversions_round_trip() {
        for convention in DayCountConvention::ALL {
            let js = JsDayCountConvention::from(convention);
            assert_eq!(DayCountConvention::from(js), convention);
        }
    }
}
